import type { ApiCollectionSchema, ApiFieldSchema } from "@gettersethya/mira-client"

export type CodegenOptions = {
  /** Emit only these collections. Default: every collection in input order. */
  readonly include?: ReadonlyArray<string>
  /** ISO timestamp for the header comment. Default: new Date().toISOString(). */
  readonly generatedAt?: string
}

const HEADER: ReadonlyArray<string> = [
  "// AUTO-GENERATED by the Mira dashboard — do not edit by hand.",
  "// Source: GET /api/_schema (generated {TIMESTAMP})",
  "// Client-only: server-side rules and indexes are not included.",
  "// Fields marked `hidden` are kept for schema fidelity; non-admin API responses omit them at runtime."
]

const IMPORTS_START = "import {"
const IMPORTS_END = '} from "@gettersethya/mira-client"'

type ImportNeeds = {
  readonly auth: boolean
  readonly base: boolean
  readonly view: boolean
  readonly create: boolean
  readonly record: boolean
  readonly update: boolean
  readonly field: boolean
}

/** Emits only the imports the generated file actually references. */
function renderImports(needs: ImportNeeds): ReadonlyArray<string> {
  const values: Array<string> = []
  if (needs.auth) values.push("AuthCollection")
  if (needs.base) values.push("BaseCollection")
  if (needs.field) values.push("Field")
  if (needs.view) values.push("ViewCollection")

  const types: Array<string> = []
  if (needs.create) types.push("CreateInput")
  if (needs.record) types.push("InferRecord")
  if (needs.update) types.push("UpdateInput")

  if (values.length === 0 && types.length === 0) return []

  const lines = [IMPORTS_START]
  for (const value of values) lines.push(`  ${value},`)
  for (const type of types) lines.push(`  type ${type},`)
  lines.push(IMPORTS_END)
  return lines
}

/** Deterministic PascalCase: "published_posts" -> "PublishedPosts"; leading digit gets "_" prefix. */
export function pascalCase(name: string): string {
  const parts = name.split(/[^A-Za-z0-9]+/).filter((part) => part.length > 0)
  const joined = parts
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

  if (joined.length === 0) return "_"
  return /^[0-9]/.test(joined) ? `_${joined}` : joined
}

/** Clicked collection plus the transitive closure of its relation targets, dependency-first. */
export function resolveSubset(
  schemas: ReadonlyArray<ApiCollectionSchema>,
  rootName: string
): ReadonlyArray<ApiCollectionSchema> {
  const byName = new Map<string, ApiCollectionSchema>()
  for (const schema of schemas) byName.set(schema.name, schema)

  const ordered: Array<ApiCollectionSchema> = []
  const seen = new Set<string>()

  const visit = (schema: ApiCollectionSchema): void => {
    if (seen.has(schema.name)) return
    seen.add(schema.name)

    for (const field of Object.values(schema.fields)) {
      if (field["x-kind"] !== "relation") continue
      const targetName = field["x-collection"]
      if (targetName === undefined) continue
      const target = byName.get(targetName)
      if (target !== undefined) visit(target)
    }

    ordered.push(schema)
  }

  const root = byName.get(rootName)
  if (root !== undefined) visit(root)

  return ordered
}

export function generateCollectionFile(
  schemas: ReadonlyArray<ApiCollectionSchema>,
  options?: CodegenOptions
): string {
  const include = options?.include
  const includedNames = new Set<string>()
  if (include !== undefined) {
    for (const name of include) includedNames.add(name)
  }

  const selected = schemas.filter(
    (schema) => include === undefined || includedNames.has(schema.name)
  )

  const { ordered, cyclic } = orderByDependencies(selected)
  const emitted = new Set<string>()
  for (const schema of ordered) emitted.add(schema.name)

  const timestamp = options?.generatedAt ?? new Date().toISOString()
  const lines: Array<string> = HEADER.map((line) =>
    line.replace("{TIMESTAMP}", timestamp)
  )

  lines.push("")
  if (cyclic) {
    lines.push("// WARNING: cyclic relations — reorder these defs manually")
    lines.push("")
  }
  for (const line of renderImports(importNeeds(ordered))) lines.push(line)
  lines.push("")

  for (const schema of ordered) {
    lines.push(renderCollectionDefinition(schema, emitted))
    lines.push("")
    for (const alias of renderTypeAliases(schema)) lines.push(alias)
    lines.push("")
  }

  lines.push(renderCollectionsMap(ordered, emitted))

  return `${lines.join("\n")}\n`
}

type DependencyOrder = {
  readonly ordered: ReadonlyArray<ApiCollectionSchema>
  readonly cyclic: boolean
}

function importNeeds(
  schemas: ReadonlyArray<ApiCollectionSchema>
): ImportNeeds {
  const writable = schemas.some((schema) => schema.kind !== "view")
  const hasFields = schemas.some((schema) =>
    Object.values(schema.fields).some((field) => field["x-system"] !== true)
  )

  return {
    auth: schemas.some((schema) => schema.kind === "auth"),
    base: schemas.some((schema) => schema.kind === "base"),
    view: schemas.some((schema) => schema.kind === "view"),
    create: writable,
    update: writable,
    record: schemas.length > 0,
    field: hasFields
  }
}

function orderByDependencies(
  schemas: ReadonlyArray<ApiCollectionSchema>
): DependencyOrder {
  const byName = new Map<string, ApiCollectionSchema>()
  for (const schema of schemas) byName.set(schema.name, schema)

  const state = new Map<string, "visiting" | "done">()
  const ordered: Array<ApiCollectionSchema> = []
  let cyclic = false

  const visit = (schema: ApiCollectionSchema): void => {
    const current = state.get(schema.name)
    if (current === "done") return
    if (current === "visiting") {
      cyclic = true
      return
    }

    state.set(schema.name, "visiting")
    for (const field of Object.values(schema.fields)) {
      if (field["x-kind"] !== "relation") continue
      const targetName = field["x-collection"]
      if (targetName === undefined) continue
      const target = byName.get(targetName)
      if (target !== undefined) visit(target)
    }
    state.set(schema.name, "done")
    ordered.push(schema)
  }

  for (const schema of schemas) visit(schema)

  return cyclic ? { ordered: schemas, cyclic: true } : { ordered, cyclic: false }
}

function renderCollectionDefinition(
  schema: ApiCollectionSchema,
  emitted: ReadonlySet<string>
): string {
  const name = pascalCase(schema.name)
  const entries = renderFieldEntries(schema, emitted)

  if (schema.kind === "view") {
    const query = escapeTemplateLiteral(schema.viewQuery ?? "")
    return [
      `export const ${name} = ViewCollection.define(`,
      `  ${JSON.stringify(schema.name)},`,
      `  \`${query}\`,`,
      `  ${renderObject(entries, 2)}`,
      ")"
    ].join("\n")
  }

  const builder = schema.kind === "auth" ? "AuthCollection" : "BaseCollection"
  return `export const ${name} = ${builder}.define(${JSON.stringify(schema.name)}, ${renderObject(entries, 0)})`
}

function renderTypeAliases(schema: ApiCollectionSchema): ReadonlyArray<string> {
  const name = pascalCase(schema.name)
  const lines = [`export type ${name}Record = InferRecord<typeof ${name}.fields>`]

  if (schema.kind !== "view") {
    lines.push(
      `export type ${name}Create = CreateInput<typeof ${name}.fields, "${schema.kind}">`
    )
    lines.push(
      `export type ${name}Update = UpdateInput<typeof ${name}.fields, "${schema.kind}">`
    )
  }

  return lines
}

function renderCollectionsMap(
  schemas: ReadonlyArray<ApiCollectionSchema>,
  emitted: ReadonlySet<string>
): string {
  const entries: Array<readonly [string, string]> = schemas
    .filter((schema) => emitted.has(schema.name))
    .map((schema): readonly [string, string] => [
      schema.name,
      pascalCase(schema.name)
    ])

  if (entries.length === 0) return "export const collections = {}"
  return `export const collections = ${renderObject(entries, 0, true)}`
}

type FieldEntry = readonly [name: string, code: string]

function renderFieldEntries(
  schema: ApiCollectionSchema,
  emitted: ReadonlySet<string>
): ReadonlyArray<FieldEntry> {
  const entries: Array<FieldEntry> = []

  for (const [fieldName, field] of Object.entries(schema.fields)) {
    if (field["x-system"] === true) continue

    if (fieldKind(field) === "relation") {
      entries.push([fieldName, renderRelationField(schema, fieldName, field, emitted)])
      continue
    }

    entries.push([fieldName, renderSimpleField(schema, fieldName, field)])
  }

  return entries
}

function renderSimpleField(
  schema: ApiCollectionSchema,
  fieldName: string,
  field: ApiFieldSchema
): string {
  const kind = fieldKind(field)
  const options: Array<string> = []

  if (kind === "text") {
    if (field.minLength !== undefined) options.push(`minLength: ${field.minLength}`)
    if (field.maxLength !== undefined) options.push(`maxLength: ${field.maxLength}`)
  }

  if (kind === "number" || kind === "integer") {
    if (field.minimum !== undefined) options.push(`minimum: ${field.minimum}`)
    if (field.maximum !== undefined) options.push(`maximum: ${field.maximum}`)
  }

  if (kind === "literalText") {
    const literal = field["x-literal"] ?? []
    options.push(`literal: ${formatValue(literal)} as const`)
  }

  if (kind === "file") {
    if (field["x-maxSize"] !== undefined) options.push(`maxSize: ${field["x-maxSize"]}`)
    if (field["x-mimeTypes"] !== undefined) {
      options.push(`mimeTypes: ${formatValue(field["x-mimeTypes"])}`)
    }
    if (field["x-protected"] !== undefined) {
      options.push(`protected: ${String(field["x-protected"])}`)
    }
  }

  if (field.default !== undefined) options.push(`default: ${formatValue(field.default)}`)
  if (field["x-hidden"] === true) options.push("hidden: true")

  const isView = schema.kind === "view"
  if (!isView && requiredNames(schema).has(fieldName) === false) {
    options.push("required: false")
  }

  const suffix = isView ? ".view()" : ""
  return `Field.${kind}(${options.length > 0 ? `{ ${options.join(", ")} }` : ""})${suffix}`
}

function renderRelationField(
  schema: ApiCollectionSchema,
  fieldName: string,
  field: ApiFieldSchema,
  emitted: ReadonlySet<string>
): string {
  const targetName = field["x-collection"]
  const targetExists = targetName !== undefined && emitted.has(targetName)
  const isView = schema.kind === "view"

  if (targetName === undefined || !targetExists) {
    const missing = targetName ?? "unknown"
    const options: Array<string> =
      field.default !== undefined ? [`default: ${formatValue(field.default)}`] : []
    if (field["x-hidden"] === true) options.push("hidden: true")
    if (!isView && requiredNames(schema).has(fieldName) === false) {
      options.push("required: false")
    }
    const call = `Field.text(${options.length > 0 ? `{ ${options.join(", ")} }` : ""})`
    const suffix = isView ? ".view()" : ""
    return `${call}${suffix} // relation target "${missing}" was not found`
  }

  const options: Array<string> = []
  if (field["x-field"] !== undefined && field["x-field"] !== "id") {
    options.push(`field: ${JSON.stringify(field["x-field"])}`)
  }
  if (field.default !== undefined) options.push(`default: ${formatValue(field.default)}`)
  if (field["x-hidden"] === true) options.push("hidden: true")
  if (!isView && requiredNames(schema).has(fieldName) === false) {
    options.push("required: false")
  }

  const suffix = isView ? ".view()" : ""
  return `Field.relation(${pascalCase(targetName)}${options.length > 0 ? `, { ${options.join(", ")} }` : ""})${suffix}`
}

function requiredNames(schema: ApiCollectionSchema): ReadonlySet<string> {
  return new Set(schema.required ?? [])
}

type BuilderKind =
  | "text"
  | "literalText"
  | "number"
  | "integer"
  | "boolean"
  | "email"
  | "date"
  | "json"
  | "relation"
  | "file"

function fieldKind(field: ApiFieldSchema): BuilderKind {
  const xKind = field["x-kind"]

  if (xKind === "literalText") return "literalText"
  if (xKind === "relation") return "relation"
  if (xKind === "file") return "file"
  if (xKind === "date") return "date"
  if (xKind === "json") return "json"
  // View `seqId` columns map back to a plain integer field.
  if (xKind === "seqId") return "integer"

  if (field.format === "email") return "email"
  if (field.type === "number") return "number"
  if (field.type === "integer") return "integer"
  if (field.type === "boolean") return "boolean"
  if (field.type === "object") return "json"

  return "text"
}

function escapeTemplateLiteral(value: string): string {
  return value
    .replace(/\\/g, "\\\\")
    .replace(/`/g, "\\`")
    .replace(/\$\{/g, "\\${")
}

function renderObject(
  entries: ReadonlyArray<FieldEntry>,
  closingIndent: number,
  quoteKeys = false
): string {
  if (entries.length === 0) return "{}"

  const indent = " ".repeat(closingIndent)
  const fields = entries
    .map(
      ([name, code]) =>
        `${indent}  ${quoteKeys ? JSON.stringify(name) : formatKey(name)}: ${withTrailingComma(code)}`
    )
    .join("\n")

  return `{\n${fields}\n${indent}}`
}

function withTrailingComma(code: string): string {
  const commentIndex = code.lastIndexOf(" //")
  if (commentIndex === -1) return `${code},`
  return `${code.slice(0, commentIndex)},${code.slice(commentIndex)}`
}

function formatKey(name: string): string {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name) ? name : JSON.stringify(name)
}

function formatValue(value: unknown): string {
  if (typeof value === "string") return JSON.stringify(value)
  if (typeof value === "number" || typeof value === "boolean") return String(value)
  if (value === null) return "null"
  if (Array.isArray(value)) return `[${value.map(formatValue).join(", ")}]`
  if (typeof value === "object") return JSON.stringify(value) ?? "undefined"
  return "undefined"
}
